using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketInput
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string PredictedLabel { get; set; } = string.Empty;
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketModelTrainer
{
    private readonly MLContext _mlContext;
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly ILogger<TicketModelTrainer> _logger;

    public TicketModelTrainer(ILogger<TicketModelTrainer> logger, IConfiguration configuration)
    {
        _mlContext = new MLContext(seed: 42);
        var dataDir = configuration["DataDirectory"]
            ?? Path.Combine(AppContext.BaseDirectory, "Data");
        _dataPath = Path.Combine(dataDir, "tickets.csv");
        _modelPath = Path.Combine(dataDir, "ticket_model.zip");
        _logger = logger;
    }

    public string ModelPath => _modelPath;

    public (double MicroAccuracy, double MacroAccuracy, double LogLoss) TrainModel()
    {
        _logger.LogInformation("Loading data from {DataPath}", _dataPath);
        var dataView = _mlContext.Data.LoadFromTextFile<TicketInput>(
            _dataPath, hasHeader: true, separatorChar: ',');

        var split = _mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);

        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy())
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training model...");
        var model = pipeline.Fit(split.TrainSet);

        _logger.LogInformation("Evaluating model...");
        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        _logger.LogInformation(
            "Metrics — MicroAccuracy: {MicroAccuracy:F4}, MacroAccuracy: {MacroAccuracy:F4}, LogLoss: {LogLoss:F4}",
            metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss);

        _mlContext.Model.Save(model, dataView.Schema, _modelPath);
        _logger.LogInformation("Model saved to {ModelPath}", _modelPath);

        return (metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss);
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/tickets")]
public class TicketController : ControllerBase
{
    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;
    private readonly TicketModelTrainer _trainer;

    public TicketController(
        PredictionEnginePool<TicketInput, TicketPrediction> predictionPool,
        TicketModelTrainer trainer)
    {
        _predictionPool = predictionPool;
        _trainer = trainer;
    }

    [HttpPost("predict")]
    public IActionResult Predict([FromBody] PredictRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject ?? string.Empty,
            Description = request.Description ?? string.Empty,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);
        return Ok(new { predictedCategory = prediction.PredictedLabel });
    }

    [HttpPost("train")]
    public IActionResult Train()
    {
        var (microAccuracy, macroAccuracy, logLoss) = _trainer.TrainModel();
        return Ok(new { microAccuracy, macroAccuracy, logLoss });
    }
}

public class PredictRequest
{
    public string? Subject { get; set; }
    public string? Description { get; set; }
    public float Priority { get; set; }
}

